<script setup lang="ts">
import { computed, nextTick, onMounted, onUnmounted, reactive, ref, watch } from 'vue';
const emit = defineEmits<{ submitted: [status: string] }>();
const countryOptions = 'Afghanistan|Albania|Algeria|Andorra|Angola|Antigua and Barbuda|Argentina|Armenia|Australia|Austria|Azerbaijan|Bahamas|Bahrain|Bangladesh|Barbados|Belarus|Belgium|Belize|Benin|Bhutan|Bolivia|Bosnia and Herzegovina|Botswana|Brazil|Brunei|Bulgaria|Burkina Faso|Burundi|Cambodia|Cameroon|Canada|Cape Verde|Central African Republic|Chad|Chile|China|Colombia|Comoros|Congo|Costa Rica|Croatia|Cuba|Cyprus|Czechia|Democratic Republic of the Congo|Denmark|Djibouti|Dominica|Dominican Republic|Ecuador|Egypt|El Salvador|Equatorial Guinea|Eritrea|Estonia|Eswatini|Ethiopia|Fiji|Finland|France|Gabon|Gambia|Georgia|Germany|Ghana|Greece|Grenada|Guatemala|Guinea|Guinea-Bissau|Guyana|Haiti|Honduras|Hungary|Iceland|India|Indonesia|Iran|Iraq|Ireland|Israel|Italy|Jamaica|Japan|Jordan|Kazakhstan|Kenya|Kiribati|Kuwait|Kyrgyzstan|Laos|Latvia|Lebanon|Lesotho|Liberia|Libya|Liechtenstein|Lithuania|Luxembourg|Madagascar|Malawi|Malaysia|Maldives|Mali|Malta|Marshall Islands|Mauritania|Mauritius|Mexico|Micronesia|Moldova|Monaco|Mongolia|Montenegro|Morocco|Mozambique|Myanmar|Namibia|Nauru|Nepal|Netherlands|New Zealand|Nicaragua|Niger|Nigeria|North Korea|North Macedonia|Norway|Oman|Pakistan|Palau|Palestine|Panama|Papua New Guinea|Paraguay|Peru|Philippines|Poland|Portugal|Qatar|Romania|Russia|Rwanda|Saint Kitts and Nevis|Saint Lucia|Saint Vincent and the Grenadines|Samoa|San Marino|Sao Tome and Principe|Saudi Arabia|Senegal|Serbia|Seychelles|Sierra Leone|Singapore|Slovakia|Slovenia|Solomon Islands|Somalia|South Africa|South Korea|South Sudan|Spain|Sri Lanka|Sudan|Suriname|Sweden|Switzerland|Syria|Taiwan|Tajikistan|Tanzania|Thailand|Timor-Leste|Togo|Tonga|Trinidad and Tobago|Tunisia|Turkey|Turkmenistan|Tuvalu|Uganda|Ukraine|United Arab Emirates|United Kingdom|United States|Uruguay|Uzbekistan|Vanuatu|Vatican City|Venezuela|Vietnam|Yemen|Zambia|Zimbabwe'.split('|');
const sections: Record<string,string[]> = {
  'Personal Information':['first_name|First Name','middle_name|Middle Name','last_name|Last Name','gender|Gender','birthday|Birthday','age|Age','civil_status|Civil Status','children|Do you have a child or children already?','country_current|Country Currently At','nationality|Nationality','first_language|First Language','second_language|Second Language','english_level|How well can you speak and understand English?','phone|Phone Number','email|Email','facebook|Facebook Account Name / Link','address|Complete Address','province|Province in the Philippines','invited_by|Who invited you?','study_source|How did you know about this study?'],
  'Employment and Background':['networking_business|Currently part of a networking business?','employment|Employment','student_course|Student strand/course and major (NA if not applicable)','work_description|Current work (NA if not applicable)'],
  'Church Information':['church_position|Position in the Church','church_name|Complete Name of Church','believer_years|Number of Years Being a Believer','church_address|Church Address'],
  'Pastor Information':['theology_studied|Did you study Theology or Seminary?','school_name|Name of School (complete name)','major|Major','study_duration|How Long Have You Studied?','level|Level','religion|Religion','denomination|Denomination','church_category|Church Category','pastor_position|Position in the Church','ministry_period|Period of Ministry (Year Started Until Now)','church_members|Approximate Number of Church Members']
};
const data=reactive<Record<string,any>>({}), privacy=ref(''), existingDocuments=ref<{id_url:string|null;picture_url:string|null}>({id_url:null,picture_url:null}), idDocument=ref<File|null>(null), picture=ref<File|null>(null), status=ref('not_started'), busy=ref(false), loading=ref(true), notice=ref(''), error=ref(''), showScrollTop=ref(false), mobileViewport=ref(false), formElement=ref<HTMLFormElement|null>(null);
const editable=computed(()=>!['submitted','approved'].includes(status.value));
const mobileSections = [...Object.keys(sections), 'Documents', 'Data Privacy Acknowledgment'];
const currentStep = ref(0);
const sectionIndex = (section: string) => mobileSections.indexOf(section);
const draftKey = () => `enrollment-draft-${data.email || location.pathname}`;
function moveStep(direction: number) {
  let next = currentStep.value + direction;
  if (direction > 0 && currentStep.value === sectionIndex('Church Information') && data.church_position === 'Non-Pastor') next = sectionIndex('Documents');
  if (direction < 0 && currentStep.value === sectionIndex('Documents') && data.church_position === 'Non-Pastor') next = sectionIndex('Church Information');
  currentStep.value = Math.max(0, Math.min(mobileSections.length - 1, next));
}
const approved = computed(() => status.value === 'approved');
function scrollToTop() { window.scrollTo({ top: 0, behavior: 'smooth' }); }
function updateScrollTop() { showScrollTop.value = window.scrollY > 240; }
function updateViewport() { mobileViewport.value = window.matchMedia('(max-width: 640px)').matches; }
function documentInvalid(kind:'id_document'|'picture') { error.value=kind==='id_document'?'Documents section: upload an identification card or ID document before submitting.':'Documents section: upload a student picture before submitting.'; }
function employmentInvalid() { error.value='Employment and Background section: provide an employment answer before submitting.'; }
const fieldKey=(entry:string)=>entry.split('|',1)[0];
function setField(entry:string,event:Event){data[fieldKey(entry)]=(event.target as HTMLInputElement).value}
function setChecked(event:Event){data.privacy_acknowledged=(event.target as HTMLInputElement).checked}
function optionsFor(entry:string):string[]{if(entry.startsWith('country_current|'))return countryOptions;if(entry.startsWith('gender|'))return ['Male','Female'];if(entry.startsWith('civil_status|'))return ['Single','Married','Widowed','Separated','Divorced'];if(entry.startsWith('english_level|'))return ['Beginner','Elementary','Intermediate','Upper-Intermediate','Advanced','Proficient'];return []}
const age=()=>{if(!data.birthday)return '';const b=new Date(data.birthday),n=new Date();let a=n.getFullYear()-b.getFullYear();if(n.getMonth()<b.getMonth()||(n.getMonth()===b.getMonth()&&n.getDate()<b.getDate()))a--;return a>=0?a:''};
async function load(){try{const r=await fetch('/api/enrollment-form',{credentials:'same-origin',headers:{Accept:'application/json'}});if(!r.ok)throw new Error('Your enrollment form is not available yet.');const b=await r.json();privacy.value=b.privacy_text;existingDocuments.value=b.documents||{id_url:null,picture_url:null};status.value=b.form?.status||'not_started';Object.assign(data,b.prefill||{},b.form?.data||{});if(status.value==='approved')localStorage.removeItem(draftKey());else{try{Object.assign(data,JSON.parse(localStorage.getItem(draftKey())||'{}'))}catch{}}if(status.value==='needs_revision')data.privacy_acknowledged=false}catch(e){error.value=(e as Error).message}finally{loading.value=false}}
function sectionForField(key:string):number {
  const name=key.split('.').pop()||key;
  for(const [section,fields] of Object.entries(sections)) if(fields.some(entry=>fieldKey(entry)===name)) return sectionIndex(section);
  if(['id_document','picture'].includes(name)) return sectionIndex('Documents');
  return sectionIndex('Data Privacy Acknowledgment');
}
async function focusInvalid(control:HTMLInputElement|HTMLSelectElement|HTMLTextAreaElement) {
  const step=control.closest<HTMLElement>('.enrollment-step');
  const heading=step?.querySelector('h2')?.textContent?.trim();
  if(heading && mobileSections.includes(heading)) currentStep.value=sectionIndex(heading);
  await nextTick();
  control.focus({ preventScroll: false });
}
async function submitForm() {
  error.value='';
  if(mobileViewport.value) {
    const invalid=[...formElement.value!.querySelectorAll<HTMLInputElement|HTMLSelectElement|HTMLTextAreaElement>('input,select,textarea')].filter(control=>control.willValidate&&!control.validity.valid);
    if(invalid.length) {
      const target=invalid[0], step=target.closest<HTMLElement>('.enrollment-step'), heading=step?.querySelector('h2')?.textContent?.trim()||'Personal Information';
      const fields=[...new Set(invalid.filter(control=>(control.closest('.enrollment-step')?.querySelector('h2')?.textContent?.trim()||'Personal Information')===heading).map(control=>control.closest('label')?.innerText.replace(/\s+/g,' ').trim()||control.name||'Required field'))];
      error.value=`Please update ${heading}: ${fields.join(', ')}.`;
      await focusInvalid(target);
      return;
    }
  }
  await save('submit');
}
async function save(action:'draft'|'submit') { busy.value=true;error.value='';notice.value='';data.age=age();const fd=new FormData();fd.append('action',action);fd.append('data',JSON.stringify(data));if(idDocument.value)fd.append('id_document',idDocument.value);if(picture.value)fd.append('picture',picture.value);const token=document.querySelector<HTMLMetaElement>('meta[name="csrf-token"]')?.content||'';try{const r=await fetch('/api/enrollment-form',{method:'POST',credentials:'same-origin',headers:{'X-CSRF-TOKEN':token,'Accept':'application/json'},body:fd}),b=await r.json();if(!r.ok){const validation=b.errors||{};if(action==='submit'&&Object.keys(validation).length){const keys=Object.keys(validation),firstSection=sectionForField(keys[0]);if(mobileViewport.value)currentStep.value=firstSection;const fields=keys.map(key=>`${key.split('.').pop()}: ${(validation[key]||[]).join(', ')}`);throw new Error(`Please update ${mobileSections[firstSection]}: ${fields.join('; ')}`)}throw new Error(b.message||Object.values(validation).flat().join(' '))}status.value=b.form.status;existingDocuments.value=b.documents||existingDocuments.value;idDocument.value=null;picture.value=null;localStorage.removeItem(draftKey());notice.value=action==='submit'?'Submitted for review.':'Draft saved.';if(action==='submit')emit('submitted',status.value);return true}catch(e){error.value=(e as Error).message;return false}finally{busy.value=false}}
watch(data, value => { if (!loading.value && editable.value) localStorage.setItem(draftKey(), JSON.stringify(value)); }, {deep:true});
async function navigateStep(direction:number) { if (await save('draft')) moveStep(direction); }
onMounted(()=>{void load();updateViewport();window.addEventListener('resize',updateViewport);window.addEventListener('scroll',updateScrollTop,{passive:true});updateScrollTop()});
onUnmounted(()=>{window.removeEventListener('resize',updateViewport);window.removeEventListener('scroll',updateScrollTop)});
</script>
<template><section class="enrollment-page"><p v-if="loading" role="status">Loading your saved enrollment form…</p><p v-else-if="error && !privacy" class="student-error" role="alert">{{ error }}</p><form v-else ref="formElement" :novalidate="mobileViewport" class="enrollment-paper" :class="{ 'enrollment-approved': approved }" @submit.prevent="submitForm"><header class="enrollment-header"><p>STUDENT ADMISSION</p><h1>OFFICIAL ENROLLMENT FORM</h1><span>Status: <b>{{ status.replace('_',' ') }}</b></span></header><p v-if="editable">Please complete each section. Your draft is saved when you choose Save Draft.</p><p v-else-if="approved">Your enrollment form has been approved. The information below is read-only.</p><fieldset class="enrollment-fields" :disabled="!editable"><div v-for="(fields,section) in sections" :key="section" class="enrollment-step" :class="{ active: currentStep===sectionIndex(section) }"><h2 v-if="section!=='Pastor Information'||data.church_position==='Pastor'">{{ section }}</h2><div v-if="section!=='Pastor Information'||data.church_position==='Pastor'" class="enrollment-grid"><label v-for="entry in fields" :key="entry">{{ entry.split('|')[1] }}<select v-if="optionsFor(entry).length" :value="data[fieldKey(entry)]||''" @change="setField(entry,$event)"><option value="">Choose…</option><option v-if="data[fieldKey(entry)]&&!optionsFor(entry).includes(data[fieldKey(entry)])" :value="data[fieldKey(entry)]">{{ data[fieldKey(entry)] }}</option><option v-for="option in optionsFor(entry)" :key="option" :value="option">{{ option }}</option></select><select v-else-if="entry.startsWith('church_position|')" :value="data.church_position||''" @change="setField(entry,$event)"><option value="">Choose…</option><option>Pastor</option><option>Non-Pastor</option></select><select v-else-if="['children','networking_business','theology_studied'].some(k=>entry.startsWith(k+'|'))" :value="data[fieldKey(entry)]||''" @change="setField(entry,$event)"><option value="">Choose…</option><option>Yes</option><option>No</option></select><input v-else-if="entry.startsWith('age|')" type="number" :value="age()" readonly aria-label="Age calculated from birthday"><textarea v-else-if="entry.startsWith('address|')" :value="data[fieldKey(entry)]??''" rows="2" required @input="setField(entry,$event)"></textarea><input v-else :value="data[fieldKey(entry)]??''" :type="entry.startsWith('birthday|')?'date':'text'" :required="['first_name','last_name','gender','birthday','civil_status','children','country_current','nationality','first_language','english_level','employment','phone','email','address'].includes(fieldKey(entry)) || (data.church_position==='Pastor'&&section==='Pastor Information')" @input="setField(entry,$event)" @invalid="entry.startsWith('employment|') && employmentInvalid()" /></label></div></div><div class="enrollment-step" :class="{ active: currentStep===sectionIndex('Documents') }"><h2>Documents</h2><div class="enrollment-grid"><label>Identification Card or ID (image or PDF)<a v-if="existingDocuments.id_url" :href="existingDocuments.id_url" target="_blank" rel="noopener noreferrer">View current ID document</a><input type="file" accept="image/jpeg,image/png,application/pdf" :required="!existingDocuments.id_url" @invalid="documentInvalid('id_document')" @change="idDocument=($event.target as HTMLInputElement).files?.[0]||null"></label><label>Picture<figure v-if="existingDocuments.picture_url" class="enrollment-existing-picture-wrap"><img class="enrollment-existing-picture" :src="existingDocuments.picture_url" alt="Currently uploaded student picture"><figcaption>Current uploaded picture</figcaption></figure><input type="file" accept="image/jpeg,image/png,image/webp" :required="!existingDocuments.picture_url" @invalid="documentInvalid('picture')" @change="picture=($event.target as HTMLInputElement).files?.[0]||null"></label></div></div><div class="enrollment-step" :class="{ active: currentStep===sectionIndex('Data Privacy Acknowledgment') }"><h2>Data Privacy Acknowledgment</h2><p class="privacy-copy">{{ privacy }}</p><label class="privacy-check"><input type="checkbox" :checked="Boolean(data.privacy_acknowledged)" @change="setChecked"> I acknowledge this statement (required to submit).</label></div></fieldset><p v-if="error" class="student-error" role="alert">{{ error }}</p><p v-if="notice" class="student-success" role="status">{{ notice }}</p><div v-if="!approved" class="enrollment-actions" :class="{ 'enrollment-final-step': currentStep===mobileSections.length-1 }"><button type="button" class="secondary-button" :disabled="busy||!editable" @click="save('draft')">Save Draft</button><button type="button" class="primary enrollment-previous" :disabled="busy||currentStep===0" @click="navigateStep(-1)">Previous</button><button type="button" class="primary enrollment-next" :disabled="busy||!editable" @click="navigateStep(1)">Next</button><button class="primary enrollment-submit" :disabled="busy||!editable">{{ busy?'Working…':status==='submitted'?'Submitted':'Submit' }}</button></div></form><button v-if="showScrollTop" type="button" class="enrollment-scroll-top" aria-label="Scroll to top of enrollment form" @click="scrollToTop">Scroll to Top</button></section></template>
